#!/bin/bash
# Build the survey (main.tex -> main.pdf) and then the standalone proposals document (8_proposals/proposals.tex -> proposals.pdf).
# main.tex is built first because proposals.tex resolves its references into the survey from build/main.aux (xr-hyper).
# Merge bib fixes, compile 3x with bibtex. Aux files go to build/.
# Layout (see README.md): one directory per section, one subdirectory per dataset:
#   <group>/<slug>/<slug>.tex   hand-written dataset section (see WRITER_GUIDE.md)
#   <group>/<slug>/traj.tex     generated by scripts/render_traj.py
#   <group>/<slug>/figures/     generated by scripts/make_figures.py
#   <group>/<slug>/refs.bib     corrected BibTeX entry for the dataset paper
#   2_overview/tables/          small \input snippets used by 2_overview/overview.tex
#   bib/refs.bib + every */refs*.bib -> bib/refs_merged.bib (generated)
set -e
export PATH=$HOME/.TinyTeX/bin/x86_64-linux:$PATH
cd "$(dirname "$0")"
mkdir -p build
python3 ../scripts/merge_bib.py bib/refs.bib . bib/refs_merged.bib
TEX="pdflatex -interaction=nonstopmode -output-directory=build"
$TEX -halt-on-error main.tex >/dev/null || { grep -A3 "^!" build/main.log | head -30; exit 1; }
bibtex build/main >/dev/null || true   # run from report/ so bib/refs_merged.bib resolves
$TEX main.tex >/dev/null
$TEX main.tex >/dev/null
cp build/main.pdf main.pdf
grep -E "^!" build/main.log | head; grep -c "Overfull" build/main.log || true
grep -E "Output written" build/main.log
# --- proposals document (standalone; reads the survey's labels from a copy of build/main.aux without its \bibcite lines,
#     so that the proposals keep their own citation numbering)
grep -v '\\bibcite' build/main.aux > build/main_labels.aux
$TEX -halt-on-error 8_proposals/proposals.tex >/dev/null || { grep -A3 "^!" build/proposals.log | head -30; exit 1; }
bibtex build/proposals >/dev/null || true
$TEX 8_proposals/proposals.tex >/dev/null
$TEX 8_proposals/proposals.tex >/dev/null
cp build/proposals.pdf proposals.pdf
grep -E "^!" build/proposals.log | head; grep -c "Overfull" build/proposals.log || true
grep -E "Output written" build/proposals.log
